const Live = function Render(args) {
  const [shown, setShown] = useState<'danger' | 'success' | null>(null)
  return (
    <div style={stack}>
      <div style={{ display: 'flex', gap: 'var(--space-2)' }}>
        <Button size="sm" appearance="outlined" onClick={() => setShown('danger')}>
          Fail
